script:
function makeTicker(durationMs, onFrame) {
  var startTs = 0, raf = 0, running = false;
  function frame(ts) {
    if (!running) return;
    if (!startTs) startTs = ts;
    var t = Math.min(1, (ts - startTs) / durationMs);
    onFrame(t);
    if (t < 1) raf = requestAnimationFrame(frame);
    else { running = false; Sandbox.progress(1); }
  }
  return {
    restart: function () { if (raf) cancelAnimationFrame(raf); startTs = 0; running = true; raf = requestAnimationFrame(frame); },
    play: function () { if (running) return; running = true; startTs = 0; raf = requestAnimationFrame(frame); },
    pause: function () { running = false; if (raf) cancelAnimationFrame(raf); raf = 0; }
  };
}
var SPEED = {{speed}};
var DURATION = Math.round(4200 / SPEED);
var stageGroup = document.getElementById('stages');
var dotGroup = document.getElementById('dots');
var caption = document.getElementById('caption');
var chip = document.getElementById('step-chip');
var STAGES = [
  { title: '是什么', hint: '先抓住定义', caption: '先抓住定义：示例概念' },
  { title: '关键点', hint: '再看作用', caption: '再分析怎么起作用' },
  { title: '收束', hint: '记住', caption: '最后辨析易混点' }
];
var N = STAGES.length;
var cardW = 120, gap = 30;
var nodes = [];
for (var s = 0; s < N; s += 1) {
  var x = 40 + s * (cardW + gap);
  var rect = Sandbox.svgEl('rect');
  rect.setAttribute('x', String(x));
  rect.setAttribute('y', '48');
  rect.setAttribute('width', String(cardW));
  rect.setAttribute('height', '88');
  rect.setAttribute('rx', '12');
  rect.setAttribute('fill', '#ffffff');
  rect.setAttribute('stroke', '#d6ddec');
  stageGroup.appendChild(rect);
  var title = Sandbox.svgEl('text');
  title.setAttribute('x', String(x + cardW / 2));
  title.setAttribute('y', '100');
  title.setAttribute('text-anchor', 'middle');
  title.setAttribute('style', 'font-size:14px;font-weight:650;fill:#12233b');
  title.textContent = STAGES[s].title;
  stageGroup.appendChild(title);
  nodes.push(rect);
}
var dot = Sandbox.svgEl('circle');
dot.setAttribute('r', '6');
dot.setAttribute('fill', '#3b82f6');
dot.setAttribute('cy', '160');
dotGroup.appendChild(dot);
function play() {
  caption.textContent = STAGES[0].caption;
  chip.textContent = '1 / ' + N;
  var handle = makeTicker(DURATION, function (t) {
    var i = Math.min(N - 1, Math.floor(t * N));
    caption.textContent = STAGES[i].caption;
    chip.textContent = (i + 1) + ' / ' + N;
    dot.setAttribute('cx', String(40 + i * (cardW + gap) + cardW / 2));
    for (var k = 0; k < N; k += 1) nodes[k].setAttribute('fill', k === i ? '#eef4ff' : '#ffffff');
    Sandbox.progress(t);
  });
  handle.restart();
  return handle;
}
Sandbox.play(play);
Sandbox.ready();
